import { useEffect, useMemo, useRef, useState } from 'react'
import '../../../figures/kit/iso.css'
import './f1car.css'

// The figure is generated by figures/f1car/build.mjs (Anatomy kit) and loaded
// lazily: ~0.9 MB of pre-built SVG for the three regulation eras.
interface EraData { label: string; floor: string; svg: string; anim: Record<string, string[]>; frames: number }
interface CarData { width: number; height: number; platform: string; eras: Record<string, EraData> }
let cached: Promise<CarData> | null = null
const loadCar = () => (cached ??= import('../../generated/f1car.json').then((m) => m.default as unknown as CarData))

type EraId = 'e2018' | 'e2022' | 'e2026'
export const eraOf = (season: number): EraId => (season <= 2021 ? 'e2018' : season <= 2025 ? 'e2022' : 'e2026')

// FIA minimum car weight including the driver (kg), by season.
const MIN_WEIGHT: Record<number, number> = { 2018: 733, 2019: 743, 2020: 746, 2021: 752, 2022: 798, 2023: 798, 2024: 798, 2025: 800, 2026: 768 }

const SPECS: Record<EraId, { wheelbase: string; width: string; wheels: string; pu: string; aero: string }> = {
  e2018: { wheelbase: 'free (≈ 3,650 mm)', width: '2,000 mm', wheels: '13-inch rims', pu: '1.6 L V6 turbo · MGU-K 120 kW + MGU-H', aero: 'DRS · rear flap opens 85 mm' },
  e2022: { wheelbase: '≤ 3,600 mm', width: '2,000 mm', wheels: '18-inch rims', pu: '1.6 L V6 turbo · MGU-K 120 kW + MGU-H · E10 fuel', aero: 'DRS · rear flap opens 85 mm' },
  e2026: { wheelbase: '≤ 3,400 mm', width: '1,900 mm', wheels: '18-inch rims, narrower tyres', pu: '1.6 L V6 · MGU-K 350 kW (≈ 50 % electric) · no MGU-H · sustainable fuel', aero: 'Active aero · front and rear flaps' },
}

const FACTS: Record<EraId, Record<string, string>> = {
  e2018: {
    frontwing: 'Front wing · 2,000 mm wide from 2019, simplified endplates to help cars follow',
    nose: 'High nose · air flows under it to the bargeboards and floor',
    chassis: 'Survival cell · carbon monocoque, crash-tested by the FIA',
    cockpit: 'Cockpit · driver seated with feet above the front axle',
    halo: 'Halo · titanium, mandatory from 2018, withstands 125 kN',
    sidepods: 'Sidepods · radiator inlets, narrow "coke-bottle" rear',
    bargeboards: 'Bargeboards · the aero battleground of the era, banned from 2022',
    mirrors: 'Mirrors · minimum size and position set by the FIA',
    engine: 'Engine cover · airbox above the driver feeds the V6 turbo',
    floor: 'Flat floor + diffuser · high rake set-ups generate downforce',
    rear: 'Crash structure · rain light and exhaust on the centreline',
    rearwing: 'Rear wing · tall endplates; DRS opens the flap 85 mm on straights',
    wheels: '13-inch wheels · 660 mm tyres with tall sidewalls',
    suspension: 'Suspension · wishbones and push/pull rods; hydraulic tricks banned',
  },
  e2022: {
    frontwing: 'Front wing · four elements bolted to the nose, designed to cut outwash',
    nose: 'Low nose · meets the mainplane directly',
    chassis: 'Survival cell · tougher crash tests from 2022',
    cockpit: 'Cockpit · driver seated with feet above the front axle',
    halo: 'Halo · titanium, withstands 125 kN; saved several drivers',
    sidepods: 'Sidepods · downwash ramps or zero-pod concepts',
    mirrors: 'Mirrors · minimum size and position set by the FIA',
    engine: 'Engine cover · airbox above the driver feeds the V6 turbo',
    floor: 'Ground-effect floor · two Venturi tunnels make most of the downforce',
    rear: 'Crash structure · rain light and exhaust on the centreline',
    rearwing: 'Rear wing · rolled tips + beam wing; DRS opens the flap 85 mm',
    wheels: '18-inch wheels · 720 mm low-profile tyres, wheel covers and wake deflectors',
    suspension: 'Suspension · simplified, no hydraulic elements',
  },
  e2026: {
    frontwing: 'Active front wing · two flaps switch to low-drag mode on straights',
    nose: 'Nose · shorter car, 100 mm narrower overall',
    chassis: 'Survival cell · stronger side and roll-hoop loads',
    cockpit: 'Cockpit · driver seated with feet above the front axle',
    halo: 'Halo · titanium, withstands 125 kN',
    sidepods: 'Sidepods · cooling for a much bigger battery',
    mirrors: 'Mirrors · minimum size and position set by the FIA',
    engine: 'Engine cover · V6 with 350 kW MGU-K, no MGU-H, 100 % sustainable fuel',
    floor: 'Partly flat floor · FIA target ≈ 30 % less downforce, 55 % less drag',
    rear: 'Crash structure · rain light and exhaust on the centreline',
    rearwing: 'Active rear wing · replaces DRS; no beam wing',
    wheels: '18-inch wheels · front tyres 25 mm, rears 30 mm narrower',
    suspension: 'Suspension · push or pull rods, simplified',
  },
}

interface Props { season: number; teams: { id: string; name: string; color: string }[] }

export default function CarFigure({ season, teams }: Props) {
  const era = eraOf(season)
  const [data, setData] = useState<CarData | null>(null)
  const [team, setTeam] = useState(teams[0]?.id)
  const [part, setPart] = useState<string | null>(null)
  const [open, setOpen] = useState(false)
  const stage = useRef<HTMLDivElement>(null)
  const readout = useRef<HTMLSpanElement>(null)

  useEffect(() => { loadCar().then(setData) }, [])
  useEffect(() => { setTeam(teams[0]?.id) }, [teams])
  const color = teams.find((t) => t.id === team)?.color ?? '#e10600'
  const E = data?.eras[era]

  const restText = `${season} · minimum ${MIN_WEIGHT[season] ?? '—'} kg · width ${SPECS[era].width}`
  const text = part ? FACTS[era][part] ?? part : restText

  // Flap animation: eased 0 (closed) -> 1 (open), swapping pre-built frames.
  const tRef = useRef(0)
  const frameRef = useRef(-1)
  useEffect(() => {
    const el = stage.current
    if (!el || !E) return
    const groups = [...el.querySelectorAll<SVGGElement>('[data-anim]')]
    const still = matchMedia('(prefers-reduced-motion: reduce)').matches
    let raf = 0, last = 0
    const draw = () => {
      const i = Math.round(tRef.current * E.frames)
      if (i === frameRef.current) return
      frameRef.current = i
      for (const g of groups) g.innerHTML = E.anim[g.dataset.anim!]?.[i] ?? ''
    }
    const tick = (now: number) => {
      const dt = last ? Math.min((now - last) / 1000, 1 / 30) : 1 / 60
      last = now
      const target = open ? 1 : 0
      tRef.current = still ? target : tRef.current + (target - tRef.current) * (1 - Math.exp(-dt / 0.18))
      if (Math.abs(target - tRef.current) < 0.004) tRef.current = target
      draw()
      raf = tRef.current === target ? 0 : requestAnimationFrame(tick)
    }
    frameRef.current = -1
    draw()
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [open, E])

  // Idle tour: the flap opens and closes like on a straight, while nobody touches it.
  const touched = useRef(false)
  useEffect(() => {
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) return
    const id = setInterval(() => { if (!touched.current) setOpen((o) => !o) }, 2600)
    return () => clearInterval(id)
  }, [])

  // Hover: delegate on the stage, light every group of the picked part.
  const onOver = (e: React.PointerEvent) => {
    const g = (e.target as Element).closest<SVGGElement>('[data-part]')
    const p = g?.dataset.part ?? null
    if (p === part) return
    stage.current?.querySelectorAll('[data-on]').forEach((n) => n.removeAttribute('data-on'))
    if (p) stage.current?.querySelectorAll(`[data-part="${p}"]`).forEach((n) => n.setAttribute('data-on', ''))
    setPart(p)
  }
  const onLeave = () => {
    stage.current?.querySelectorAll('[data-on]').forEach((n) => n.removeAttribute('data-on'))
    setPart(null)
  }
  const toggle = () => { touched.current = true; setOpen((o) => !o) }

  const svg = useMemo(() => (E && data ? `<svg class="iso-svg" viewBox="0 0 ${data.width} ${data.height}" role="img" aria-label="Isometric drawing of a ${E.label} Formula 1 car on an FIA scrutineering platform">${data.platform}${E.floor}${E.svg}</svg>` : ''), [E, data])

  return (
    <section className="card car-card" style={{ marginTop: 16 }}>
      <div className="card-head">
        <h2>The car · {SPECS[era] && E?.label} regulations</h2>
        <div className="seg" role="group" aria-label="Livery">
          {teams.slice(0, 10).map((t) => (
            <button key={t.id} className={t.id === team ? 'on' : ''} onClick={() => setTeam(t.id)} title={t.name} style={t.id === team ? { background: t.color, color: '#0b0b10' } : undefined}>
              <i className="tdot" style={{ background: t.color }} /> {t.name.split(' ')[0]}
            </button>
          ))}
        </div>
      </div>
      <div className="iso f1car iso-plate car-plate" style={{ ['--team' as string]: color }}>
        <div className="iso-plate-corners" aria-hidden>
          <span className="iso-plate-corner" data-corner="fig">Fig 1</span>
          <span className="iso-plate-corner" data-corner="title">FIA scrutineering · {E?.label ?? ''}</span>
          <span className="iso-plate-corner" data-corner="hint">Hover a part · click to {era === 'e2026' ? 'switch aero mode' : 'open DRS'}</span>
          <span className="iso-plate-corner" data-corner="readout" ref={readout}>{text}</span>
        </div>
        {svg ? (
          <div ref={stage} className="car-stage" tabIndex={0} role="button" aria-pressed={open}
            aria-label={`${E?.label} car. Press to ${era === 'e2026' ? 'switch active aero' : 'open DRS'}. ${text}`}
            onPointerOver={onOver} onPointerLeave={onLeave} onClick={toggle}
            onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle() } }}
            dangerouslySetInnerHTML={{ __html: svg }} />
        ) : <div className="car-loading">Loading drawing…</div>}
      </div>
      <div className="car-legend">
        <span><i className="key key-lit" /> {SPECS[era].aero}: the lit flap {open ? 'open' : 'closed'}</span>
        <span><i className="key key-team" style={{ background: color }} /> Bodywork in team colours</span>
        <span><i className="key key-tick" /> Ruler ticks every 100 mm · white markers show wheelbase and overall width</span>
      </div>
      <dl className="car-specs">
        <div><dt>Min. weight</dt><dd>{MIN_WEIGHT[season] ?? '—'} kg</dd></div>
        <div><dt>Wheelbase</dt><dd>{SPECS[era].wheelbase}</dd></div>
        <div><dt>Width</dt><dd>{SPECS[era].width}</dd></div>
        <div><dt>Wheels</dt><dd>{SPECS[era].wheels}</dd></div>
        <div><dt>Power unit</dt><dd>{SPECS[era].pu}</dd></div>
      </dl>
    </section>
  )
}
